pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, address recipient, uint256 v) public {
        vm.assume(recipient != from);
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        Recorder rec = new Recorder();
        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok && rec.recipient() == recipient);
    }
}

contract Recorder {
    address public recipient;
    function transferFrom(address, address to, uint256) external returns (bool) {
        recipient = to;
        return true;
    }
}
